def components(uv, minimum=12):
 if not len(uv):return []
 # Connected ordered native points; multiple-return candidate table is not
 # sorted into a single fabricated trace. These summaries apply acceptedclouds only.
 ends=np.r_[0,np.flatnonzero((np.diff(uv[:,0])>3)|(abs(np.diff(uv[:,1]))>8))+1,len(uv)];result=[]
 for a,b in zip(ends[:-1],ends[1:]):
  if b-a<minimum:continue
  q=uv[a:b];result.append({'native_start_index':int(a),'native_stop_exclusive':int(b),'count':int(b-a),'uv_first':q[0].tolist(),'uv_last':q[-1].tolist(),'uv_min':q.min(axis=0).tolist(),'uv_max':q.max(axis=0).tolist()})
